import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import './Quiz.css'; // Make sure this path is correct for your project structure

// Detailed outfit suggestions (unchanged)
const outfitSuggestions = {
    Classic: {
        "Work / Formal": "Tailored blazer, structured vest, wide-leg trousers, and minimal accessories.",
        "Party / Festive": "Flowing satin midi dress with a tie-neck, paired with a structured bag, refined watch, and elegant slingback heels.",
        "Casual / Street": "A white tee and classic blue jeans, complemented by comfortable loafers.",
        "Vacation / Travel": "A midi dress with ruffled detailing, complemented by a wide-brimmed sun hat, stylish sunglasses, a spacious tote bag, and comfortable flat sandals."
    },
    Boho: {
        "Work / Formal": "A soft satin wrap top and flowing wide-leg trousers, combined with pointed-toe heels, a structured belt, and chic sunglasses.",
        "Party / Festive": "A floral halter-neck dress, high heels, a structured bag, and delicate layered jewelry.",
        "Casual / Street": "A comfortable crop top with a tiered maxi skirt, layered with a cream cardigan, accessorized with black Mary Jane flats, a two-toned shoulder bag, and classic glasses.",
        "Vacation / Travel": "A loose-fitting, tiered, embroidered midi dress, a large straw tote bag, and simple flat-style sandals."
    },
    Chic: {
        "Work / Formal": "A short-sleeved collared shirt and wide-leg trousers paired with a statement belt, sophisticated gold jewelry, sleek sunglasses, a structured handbag, a classic watch, and nude pointed-toe heels.",
        "Party / Festive": "A ruffled camisole top, black wide-leg trousers, high-heeled sandals, and a structured handbag.",
        "Casual / Street": "A puff-sleeve top with playful tie details, styled with wide-leg jeans, completed with pink high heels, a stylish tweed bag, and gold accessories.",
        "Vacation / Travel": "A blue and white floral midi dress, a large straw tote bag, and comfortable white block-heeled sandals."
    },
    Streetwear: {
        "Work / Formal": "A classic trench coat layered over casual wear, paired with wide-leg jeans, comfortable sneakers, and a structured shoulder bag with subtle gold accessories.",
        "Party / Festive": "A bold neon green spaghetti strap crop top with light blue wide-leg denim cargo jeans, accessorized with a matching neon green shoulder bag, light-tinted rectangular sunglasses, and checkered white slip-on sneakers.",
        "Casual / Street": "A monochrome lavender ensemble featuring a relaxed-fit, long-sleeved button-up shirt worn over a matching lavender tank top, paired with light wash, wide-leg jeans, white sneakers, and a small, structured lavender top-handle bag.",
        "Vacation / Travel": "An oversized, jersey-style top with a large number '99', paired with light blue denim shorts, comfortable green sneakers, a black crescent-shaped shoulder bag, and stylish hexagonal sunglasses."
    }
};

const Quiz = () => {
    const [style, setStyle] = useState("");
    const [occasion, setOccasion] = useState("");
    const navigate = useNavigate();

    const handleSubmit = (e) => {
        e.preventDefault(); // Prevent default form submission behavior

        if (!style || !occasion) {
            alert("Please select both a style and an occasion.");
            return; // Stop the function if selections are missing
        }

        // Generate the outfit suggestion based on selections
        const outfit = outfitSuggestions[style]?.[occasion] || "No suggestion available for this combination.";

        // Navigate to the Result page, passing the selected data as state
        navigate("/result", {
            state: {
                style,
                occasion,
                outfit
            }
        });
    };

    return (
        <div className="quiz-container">
            <h2 className="quiz-title">👗 MyStyleDNA Quiz</h2>
            <form onSubmit={handleSubmit} className="quiz-form">
                <div>
                    <label htmlFor="style-select" className="quiz-label">
                        ✨ Select your fashion style:
                    </label>
                    <select
                        id="style-select"
                        value={style}
                        onChange={(e) => setStyle(e.target.value)}
                        required
                        className="quiz-select"
                    >
                        <option value="">-- Select Style --</option>
                        <option value="Classic">Classic</option>
                        <option value="Boho">Boho</option>
                        <option value="Chic">Chic</option>
                        <option value="Streetwear">Streetwear</option>
                    </select>
                </div>

                <div>
                    <label htmlFor="occasion-select" className="quiz-label">
                        🎯 Select the occasion:
                    </label>
                    <select
                        id="occasion-select"
                        value={occasion}
                        onChange={(e) => setOccasion(e.target.value)}
                        required
                        className="quiz-select"
                    >
                        <option value="">-- Select Occasion --</option>
                        <option value="Work / Formal">Work / Formal</option>
                        <option value="Party / Festive">Party / Festive</option>
                        <option value="Casual / Street">Casual / Street</option>
                        <option value="Vacation / Travel">Vacation / Travel</option>
                    </select>
                </div>

                <button
                    type="submit"
                    className="quiz-button"
                >
                    Show My Style
                </button>
            </form>
        </div>
    );
};

export default Quiz;
